// frontend/src/context/AuthContext.js
import React, { createContext, useContext, useEffect, useState } from 'react';
import axios from 'axios';
import { auth, signInWithCustomToken, onAuthStateChanged } from '../config/firebase';
import { getIdToken, signOut as firebaseSignOut } from 'firebase/auth';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:5000/api';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);     // firebase user (minimal)
  const [idToken, setIdToken] = useState(null); // Firebase ID token (string)
  const [loading, setLoading] = useState(true);

  // Attach token to axios defaults
  useEffect(() => {
    if (idToken) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${idToken}`;
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
  }, [idToken]);

  // Listen to auth changes (client-side)
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser) {
        setUser({ uid: fbUser.uid, email: fbUser.email });
        const token = await getIdToken(fbUser, /* forceRefresh */ true);
        setIdToken(token);
      } else {
        setUser(null);
        setIdToken(null);
      }
      setLoading(false);
    });
    return () => unsub();
  }, []);

  // Backend login: call /api/auth/login -> returns customToken -> exchange with signInWithCustomToken
  const login = async ({ email, password }) => {
    const res = await axios.post(`${API_BASE}/auth/login`, { email, password });
    if (!res.data || !res.data.token) {
      throw new Error(res.data?.error || 'Login failed');
    }
    // backend returns a Firebase custom token; exchange with client SDK
    await signInWithCustomToken(auth, res.data.token);
    // onAuthStateChanged will pick up the user and idToken
    return true;
  };

  // Backend register: call /api/auth/register -> returns customToken -> exchange
  const register = async ({ email, password, role, userData = {} }) => {
    const res = await axios.post(`${API_BASE}/auth/register`, { email, password, role, userData });
    if (!res.data || !res.data.token) {
      throw new Error(res.data?.error || 'Registration failed');
    }
    await signInWithCustomToken(auth, res.data.token);
    return true;
  };

  const logout = async () => {
    try {
      await firebaseSignOut(auth);
      setUser(null);
      setIdToken(null);
      delete axios.defaults.headers.common['Authorization'];
    } catch (err) {
      console.error('Logout error', err);
    }
  };

  const value = {
    user,
    idToken,
    loading,
    login,
    register,
    logout,
    apiBase: API_BASE,
    axios // expose axios for direct calls
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
